<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import type {DesignSnapshot,DesignOperation} from '@schubert/contracts';
  import {parseMillimetres} from '@schubert/geometry';
  let {snapshot,measureId,label,elementId,field,onchange,actorId='',evidence=[],disabled=false,canConfirm=false}:{snapshot:DesignSnapshot;measureId:string|null;label:string;elementId?:string;field?:string;onchange:(ops:DesignOperation[])=>void;actorId?:string;evidence?:any[];disabled?:boolean;canConfirm?:boolean}=$props();
  const controlId=$props.id();
  const measure=$derived(measureId?snapshot.measurements[measureId]:null);let error=$state(''),survey=$state(false),value=$state(''),method=$state(''),evidenceId=$state(''),plus=$state(''),minus=$state(''),when=$state('');
  const meanings={design_target:'Wunschmaß',as_built:'Aufmaß',catalog_nominal:'Katalognennmaß',derived:'Referenzmaß'};
  function commit(event:Event){error='';const text=(event.currentTarget as HTMLInputElement).value;const parsed=text.trim()?parseMillimetres(text):null;if(text.trim()&&parsed===null){error='Bitte ein eindeutiges Maß in mm eingeben, z. B. 35,5.';return;}if(measureId)onchange([{type:'set_design_target',measureId,valueMm:parsed,isEstimated:false}]);else if(elementId&&field){const id=crypto.randomUUID();onchange([{type:'set_design_target',measureId:id,valueMm:parsed,isEstimated:false},{type:'bind_measurement',elementId,field:field as any,measureId:id}]);}}
  function record(event:SubmitEvent){event.preventDefault();error='';const v=parseMillimetres(value),p=parseMillimetres(plus),m=parseMillimetres(minus);if(v===null||p===null||m===null||!method.trim()||!evidenceId||!when){error='Messwert, Methode, Datum, Evidenz und beide Toleranzen vollständig angeben.';return;}const id=crypto.randomUUID();const ops:DesignOperation[]=[{type:'record_survey_measurement',measureId:id,valueMm:v,evidenceVersionId:evidenceId,measurementMethod:method,measuredBy:actorId,measuredAt:new Date(when).toISOString(),tolerancePlusMm:p,toleranceMinusMm:m}];if(elementId&&field)ops.push({type:'bind_measurement',elementId,field:field as any,measureId:id});onchange(ops);survey=false;}
</script>
<div class="measurement" data-measure-id={measureId}>
  <label for={controlId}>{label}<span>mm</span></label>
  <input id={controlId} aria-invalid={!!error} aria-describedby={controlId+'-status'} inputmode="decimal" type="text" value={measure?.valueMm?.replace('.',',')??''} placeholder="Unbekannt" disabled={disabled||!!measure&&measure.semantic!=='design_target'||!measure&&!elementId} onchange={commit}/>
  <div class="measure-status" id={controlId+'-status'}><span>{measure?meanings[measure.semantic]:'Noch kein Maß'}</span><span class:estimated={measure?.isEstimated}>{measure?.isEstimated?'Geschätzt':measure?.reviewStatus==='confirmed'?(measure.semantic==='as_built'?'Gemessen · bestätigt':'Festgelegt'):'Noch zu prüfen'}</span></div>
  {#if measure?.semantic==='design_target'&&measure.valueMm!==null&&!measure.isEstimated&&measure.reviewStatus!=='confirmed'&&!disabled&&canConfirm}<button class="text-action" onclick={()=>onchange([{type:'confirm_design_target',measureId:measureId!,confirmedBy:actorId,confirmedAt:new Date().toISOString()}])}>Wunschmaß festlegen</button>{/if}
  {#if measure?.semantic==='as_built'&&measure.reviewStatus!=='confirmed'&&!disabled&&canConfirm}<button class="text-action" onclick={()=>onchange([{type:'confirm_survey_measurement',measureId:measureId!,confirmedBy:actorId,confirmedAt:new Date().toISOString()}])}>Aufmaß fachlich bestätigen</button>{/if}
  {#if !disabled&&elementId&&field}<button class="text-action secondary-action" onclick={()=>{survey=!survey;when=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);}}>Neues Aufmaß erfassen</button>{/if}
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  {#if survey}<form class="survey-form" onsubmit={record}>
    <strong>Neue, getrennte Aufmaßversion</strong><p>Das Wunschmaß bleibt erhalten. Nur berechtigte interne Fachpersonen dürfen ein Aufmaß bestätigen.</p>
    <label>Gemessener Wert (mm)<input bind:value inputmode="decimal" required/></label>
    <label>Messmethode<input bind:value={method} placeholder="Zum Beispiel Laser mit Kontrollmessung" required/></label>
    <label>Gemessen am<input type="datetime-local" bind:value={when} required/></label>
    <label>Revisionsgebundene Evidenz<select use:searchableSelect={evidenceId} bind:value={evidenceId} required><option value="">Nachweis auswählen</option>{#each evidence as entry}<option value={entry.version_id??entry.document_version_id??entry.id}>{entry.name??entry.title??entry.original_name??entry.id}</option>{/each}</select></label>
    {#if !evidence.length}<p>Erst einen Messnachweis in der Dokumentenakte ablegen. Ein freies Bild ist kein bestätigtes Aufmaß.</p>{/if}
    <div class="tolerance"><label>Toleranz + (mm)<input bind:value={plus} inputmode="decimal" required/></label><label>Toleranz − (mm)<input bind:value={minus} inputmode="decimal" required/></label></div>
    <div class="survey-actions"><button type="button" class="btn small" onclick={()=>survey=false}>Abbrechen</button><button type="submit" class="btn small primary" disabled={!evidence.length}>Aufmaß speichern</button></div>
  </form>{/if}
</div>
<style>.measurement{margin:0 0 18px}.measurement>label{display:flex;justify-content:space-between;font-size:12px;font-weight:600;color:var(--ink);margin-bottom:7px}.measurement label span{font-weight:400;color:var(--muted)}.measurement input,.measurement select{width:100%;border:1px solid var(--line);background:var(--paper);min-height:44px;padding:8px 10px;border-radius:9px;color:var(--ink);font:inherit;font-size:14px;font-variant-numeric:tabular-nums}.measurement input:focus,.measurement select:focus{outline:2px solid var(--forest);outline-offset:2px}.measurement input:disabled{background:var(--wash);color:var(--muted)}.measure-status{font-size:10px;display:flex;justify-content:space-between;color:var(--muted);margin-top:6px;gap:7px}.measure-status .estimated{color:var(--muted)}.text-action{background:none;border:0;color:var(--forest);font-size:11px;font-weight:600;padding:6px 0;min-height:30px;text-align:left;cursor:pointer;display:block}.secondary-action{font-weight:400;text-decoration:underline;text-underline-offset:3px}.survey-form{margin-top:10px;padding:14px;background:var(--wash);border:1px solid var(--line)}.survey-form label{font-size:11px;display:block;margin-top:12px}.survey-form label input,.survey-form label select{margin-top:5px;font-size:12px}.survey-form p{font-size:11px;line-height:1.6}.survey-form strong{font-size:12px}.tolerance{display:grid;grid-template-columns:1fr 1fr;gap:8px}.survey-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.error{font-size:11px;color:var(--danger)}@media(max-width:720px){.measurement input,.measurement select{min-height:48px;font-size:16px}.text-action{min-height:44px;font-size:13px}}.measurement>label{font-size:13px}.measure-status,.text-action{font-size:12px}.measure-status{align-items:center;line-height:1.5}.measure-status>span:first-child{font-weight:500}.measurement input[aria-invalid=true]{border-color:var(--danger);background:var(--danger-wash)}.survey-form label,.survey-form p{font-size:12px}@media(max-width:720px){.text-action{min-height:48px}}
</style>
